  const blank = "<br><br>";
  const schemeTable = S => { const chain = CHAIN.has(S.type); return `| Блок схемы | Запишите по ходу урока |\n|---|---|\n${S.steps.map((x, i) => `| ${cell(x)}${chain && i < S.steps.length - 1 ? " ↓" : ""} | ${blank} |`).join("\n")}\n`; };
