    const probs = probsOf(p, 3), hwp = probsOf(p, 3, "hw"), Q = qualOf(p, kind, terms), acts = actsOf(F), val = valueOf(p, kind), fo = formulasOf(p), facts = c.facts || [], ex = c.ex || [], hwx = HW(p, M, hwp, Q, kind), thesis = c.d || `Согласны ли вы с выводом по теме «${short(p.topic)}»? Приведите два аргумента.`;
